import math, random

def dcg(rels):
    return sum(r / math.log2(i + 2) for i, r in enumerate(rels[:10]))

def ndcg10(ranked, grades):
    ideal = sorted(grades.values(), reverse=True)
    got = [grades.get(d, 0) for d in ranked]
    return dcg(got) / dcg(ideal) if dcg(ideal) else 0.0

def recall_at(ranked, grades, k):
    rel = {d for d, g in grades.items() if g > 0}
    return len(rel & set(ranked[:k])) / len(rel) if rel else 0.0

def rr(ranked, grades):
    for i, d in enumerate(ranked, 1):
        if grades.get(d, 0) > 0:
            return 1 / i
    return 0.0

def paired_bootstrap(diffs, iters=2000, seed=1):
    rng = random.Random(seed)
    means = sorted(sum(rng.choices(diffs, k=len(diffs))) / len(diffs) for _ in range(iters))
    return means[int(0.025 * iters)], means[int(0.975 * iters)]

def verdict(diffs, tol=0.01):
    lo, hi = paired_bootstrap(diffs)
    # Tricky part: block only when the whole interval is below -tol; a noisy dip is not a regression.
    return "block" if hi < -tol else "pass", lo, hi

