def run_leak_suite(fx, doors, queries):
    leaks, over, n = [], 0, 0
    allowed = {d["id"]: set(d["allowed_users"]) for d in fx["canary_docs"]}
    marks = {d["marker"]: d["id"] for d in fx["canary_docs"]}
    for u in fx["users"]:
        tok = login(u["id"])
        for q in queries:
            for door in doors:                           # MCP and REST, both
                out = door.search(tok, q)                # full text of every output path
                n += 1
                text = out.raw_text()
                for m, did in marks.items():
                    seen = m in text or did in out.ids()
                    if seen and u["id"] not in allowed[did]:
                        leaks.append({"user": u["id"], "doc": did, "path": door.name, "trace": out.trace_id})
                    if (not seen) and u["id"] in allowed[did] and q.targets(did):
                        over += 1                        # overblock: allowed user cannot find it
    # Rule of three: zero leaks in n probes bounds the rate below about 3/n with 95% confidence.
    bound = 1 - 0.05 ** (1 / n) if not leaks else None
    return dict(n_probes=n, n_leaks=len(leaks), leaks=leaks, n_overblock=over, bound95=bound)

def test_no_leaks():
    r = run_leak_suite(load_fixture(), [mcp_door, rest_door], build_plan())
    assert r["n_leaks"] == 0, r["leaks"]   # any leak blocks the release

