def price_at(prices, key, at):
    rows = [p for p in prices[key] if p["from"] <= at]
    return max(rows, key=lambda p: p["from"])["usd"]      # price in force when the call happened

def price_doc(prices, m, at, months=1):
    parts = {
        "context": m.ctx_tokens * price_at(prices, "ctx_token", at),
        "embed":   m.embed_tokens * price_at(prices, "embed_token", at),
        "store":   m.bytes_stored * price_at(prices, "byte_month", at) * months,
        "app":     m.app_calls * price_at(prices, "app_call", at),
    }
    return CostRecord(subject="doc", usd=sum(parts.values()), parts=parts)

def price_query(prices, m, at):
    parts = {
        "embed":  m.embed_tokens * price_at(prices, "embed_token", at),
        "rerank": m.rerank_docs * price_at(prices, "rerank_doc", at),
        "live":   m.live_calls * price_at(prices, "app_call", at),
        "model":  m.model_in * price_at(prices, "model_in_token", at)
                  + m.model_out * price_at(prices, "model_out_token", at),
    }
    # Tricky part: keep the parts. A total alone cannot tell you which part grew.
    return CostRecord(subject="query", usd=sum(parts.values()), parts=parts)

