def replay(store, retriever, live, query_id, generation=None):
    t = store.get(query_id)
    q = decrypt(t.tenant_id, t.query_enc)
    gen = generation or t.index_generation
    # Replay against the stored ACL snapshot so permissions do not change the ranking under test.
    res = retriever.retrieve(q, tenant=t.tenant_id, principal=t.principal_id,
                             index_generation=gen, acl_snapshot=t.acl_snapshot_version)
    old, new = t.rerank_order, res.ranked_ids
    diffs = [{"doc_id": d, "old_rank": old.index(d) if d in old else None,
              "new_rank": new.index(d) if d in new else None}
             for d in dict.fromkeys(old + new)
             if (old.index(d) if d in old else None) != (new.index(d) if d in new else None)]
    drift = []
    for c in t.live_calls:
        # Tricky part: compare hashes, never text. A changed hash means the source moved, not the index.
        now_hash = live.content_hash(c["source"], c["doc_id"], principal=t.principal_id)
        if now_hash != c["content_hash"]:
            drift.append({"doc_id": c["doc_id"], "old_hash": c["content_hash"], "new_hash": now_hash})
    return {"query_id": query_id, "same_ranking": old == new, "diffs": diffs, "drift": drift}

