def attribute(gw, trace, flag):
    out = gw.json(model=SMALL, schema=Attr, prompt=render(trace, flag))
    if any(i >= len(trace.lines) for i in out.evidence_lines):
        raise BadEvidence()
    if flag.kind == "leak":
        page_security(trace)
    stage = out.stage if out.confidence >= 0.5 else "unclear"
    return Failure(trace.query_id, stage, out.confidence, out.evidence_lines)

