def decide(new, old, margin=0.02, lat=1.1):
    if new.leak > 0 or new.perm_fail > 0:
        return "hold"                                          # hard block, no waiver
    if new.quality < old.quality - margin:
        return "roll_back"
    if new.p95_ms > lat * old.p95_ms:
        return "hold"
    return "promote"
